"""Royal Clip — clipboard watcher + always-on-top floating notebook bubble (Windows/Linux/macOS, tkinter).
Visible by design: the 📒 bubble is always on screen while capture runs; right-click → ⏸ pause. Passwords/OTPs/card numbers are skipped
locally before anything is sent. Clips go to <BASE>/bb/link/clip with the device link token; kept 30 days on the server."""
import re, json, time, threading, base64, io, hashlib, os
import urllib.request as U
SENS = [re.compile(p, re.I) for p in (r'\b\d{4,8}\b.{0,40}\b(otp|code|কোড|পিন|pin|verification)\b', r'\b(otp|code|কোড|pin|verification)\b.{0,40}\b\d{4,8}\b',
        r'^\s*\d{4,8}\s*$', r'(password|passwd|pwd|পাসওয়ার্ড)\s*[:=]', r'-----BEGIN [A-Z ]*PRIVATE KEY', r'\b(sk|pk|ghp|gho|xox[bpa]|AKIA)[-_A-Za-z0-9]{16,}')]
def _luhn(s):
    d = [int(c) for c in re.sub(r'\D', '', s)][::-1]
    return 13 <= len(d) <= 19 and sum(x if i % 2 == 0 else (x * 2 - 9 if x * 2 > 9 else x * 2) for i, x in enumerate(d)) % 10 == 0
def sensitive(t):
    if any(p.search(t) for p in SENS): return True
    if any(_luhn(m.group(0)) for m in re.finditer(r'(?:\d[ -]?){13,19}', t)): return True
    s = t.strip()
    return ' ' not in s and 8 <= len(s) <= 64 and not s.startswith(('http', 'www')) and '@' not in s and sum(bool(re.search(p, s)) for p in (r'[a-z]', r'[A-Z]', r'\d', r'[^\w]')) >= 3
PAUSE_F = os.path.expanduser('~/.rbt_clip_pause')
class Doyel:
    def __init__(self, base, token, status=None):
        self.base, self.tok, self.status = base.rstrip('/'), token, status or {}
        self.paused = os.path.exists(PAUSE_F); self.last = None; self.root = None; self.mini = None
    def post(self, path, data):
        req = U.Request(self.base + path, data=json.dumps(data).encode(), method='POST', headers={'Content-Type': 'application/json', 'User-Agent': 'RoyalLink/2.1'})
        with U.urlopen(req, timeout=20) as r: return json.loads(r.read())
    def get(self, path):
        with U.urlopen(U.Request(self.base + path, headers={'User-Agent': 'RoyalLink/2.1'}), timeout=20) as r: return json.loads(r.read())
    def send(self, kind, content):
        def go():
            try: self.post('/bb/link/clip', {'token': self.tok, 'kind': kind, 'content': content})
            except Exception as e: print('clip send failed', e)
        threading.Thread(target=go, daemon=True).start()
    def poll(self):
        try:
            if not self.paused:
                try: t = self.root.clipboard_get()
                except Exception: t = None
                if t:
                    h = hashlib.sha1(t.encode('utf-8', 'ignore')).hexdigest()
                    if h != self.last:
                        first = self.last is None; self.last = h
                        if not first and t.strip() and len(t) < 200000 and not sensitive(t): self.send('text', t); self.root.after(0, self.react, 'clip')
                else:
                    try:
                        from PIL import ImageGrab, Image
                        im = ImageGrab.grabclipboard()
                        if isinstance(im, Image.Image):
                            h = hashlib.sha1(im.tobytes()[:200000]).hexdigest()
                            if h != self.last:
                                first = self.last is None; self.last = h
                                if not first:
                                    im.thumbnail((1280, 1280)); b = io.BytesIO(); im.convert('RGB').save(b, 'JPEG', quality=70)
                                    self.send('image', 'data:image/jpeg;base64,' + base64.b64encode(b.getvalue()).decode())
                    except Exception: pass
        finally: self.root.after(1200, self.poll)
    def toggle_pause(self):
        self.paused = not self.paused
        if self.paused: open(PAUSE_F, 'w').close()
        elif os.path.exists(PAUSE_F): os.remove(PAUSE_F)
        self.paint()
    # ───────── doyel brain: weighted, time-of-day (Dhaka) & context-aware behaviour ─────────
    # fly ↔ perch on window tops / taskbar / desktop icons → walk · forage (peck + crumbs/insect) · drink · sing · preen · bathe/shake · look around
    # night nap · startle on fast mouse · curious approach to a still cursor · flies to cursor on new clip · sits on the active window while an AI job runs
    S = 128; FOOT = 124; LB = ('🕊 উড়ে যাও', '🪵 কোথাও বসো', '🐛 খাবার খোঁজো', '👧 মামণিকে আনো')
    def img(self, name):
        if not getattr(self, 'imgs', None):
            import tkinter as tk; self.imgs = {k: tk.PhotoImage(data=v) for k, v in DOYEL.items()}
        return self.imgs[name + ('_L' if self.face < 0 else '')]
    def paint(self):
        c = self.cv
        if not getattr(self, 'sprite', None):
            self.sprite = c.create_image(self.S // 2, self.S // 2, image=self.img('perch0')); self.ptxt = c.create_text(14, 14, text='', font=('Segoe UI Emoji', 10), fill='white')
        c.itemconfig(self.sprite, image=self.img(self.pose))
        c.itemconfig(self.ptxt, text='⏸' if self.paused else '📌' if self.state == 'pinned' else '⚙' if self.busy else '💤' if self.state == 'sleep' else '')
    def bounds(self):
        try:
            import ctypes; u = ctypes.windll.user32
            x, y, w, h = u.GetSystemMetrics(76), u.GetSystemMetrics(77), u.GetSystemMetrics(78), u.GetSystemMetrics(79)
            if w > 0: return x, y, x + w - self.S, y + h - self.S
        except Exception: pass
        return 0, 0, self.root.winfo_screenwidth() - self.S, self.root.winfo_screenheight() - self.S
    def noactivate(self):
        try:
            import ctypes; u = ctypes.windll.user32; hw = u.GetParent(self.root.winfo_id()) or self.root.winfo_id(); self.hwnd = hw
            u.SetWindowLongW(hw, -20, u.GetWindowLongW(hw, -20) | 0x08000000 | 0x80)  # WS_EX_NOACTIVATE | TOOLWINDOW
        except Exception: pass
    # ---- perch surfaces: (x, edge_y, kind, hwnd, xmin, xmax) ----
    def taskbar_top(self):
        try:
            import ctypes, ctypes.wintypes as W
            class ABD(ctypes.Structure): _fields_ = [('cbSize', W.DWORD), ('hWnd', W.HWND), ('uCallbackMessage', W.UINT), ('uEdge', W.UINT), ('rc', W.RECT), ('lParam', W.LPARAM)]
            a = ABD(); a.cbSize = ctypes.sizeof(a)
            if ctypes.windll.shell32.SHAppBarMessage(5, ctypes.byref(a)) and a.uEdge == 3: return a.rc.left, a.rc.top, a.rc.right
            r = W.RECT(); ctypes.windll.user32.SystemParametersInfoW(0x30, 0, ctypes.byref(r), 0); return r.left, r.bottom, r.right
        except Exception: return 0, self.root.winfo_screenheight() - 40, self.root.winfo_screenwidth()
    def win_rect(self, hw):
        import ctypes, ctypes.wintypes as W
        r = W.RECT()
        if ctypes.windll.dwmapi.DwmGetWindowAttribute(W.HWND(hw), 9, ctypes.byref(r), ctypes.sizeof(r)) != 0: ctypes.windll.user32.GetWindowRect(hw, ctypes.byref(r))
        return r.left, r.top, r.right, r.bottom
    def windows(self):
        out = []
        try:
            import ctypes, ctypes.wintypes as W; u = ctypes.windll.user32; me = getattr(self, 'hwnd', 0)
            def cb(hw, _):
                try:
                    if hw == me or not u.IsWindowVisible(hw) or u.IsIconic(hw) or u.GetWindowTextLengthW(hw) == 0: return True
                    cl = ctypes.c_int(0); ctypes.windll.dwmapi.DwmGetWindowAttribute(W.HWND(hw), 14, ctypes.byref(cl), 4)
                    if cl.value or u.GetWindowLongW(hw, -20) & 0x80: return True
                    l, t, r, b = self.win_rect(hw)
                    if r - l > 320 and b - t > 200: out.append((l, t, r, b, hw))
                except Exception: pass
                return True
            u.EnumWindows(ctypes.WINFUNCTYPE(ctypes.c_bool, W.HWND, W.LPARAM)(cb), 0)
        except Exception: pass
        return out
    def spots(self):
        import random; x0, y0, x1, y1 = self.bounds(); sp = []; wins = self.windows()
        for i, (l, t, r, b, hw) in enumerate(wins[:8]):
            if t < y0 + 50 or any(L < (l + r) // 2 < R and T < t < B for L, T, R, B, _ in wins[:i]): continue
            sp += [(random.randint(l + 60, r - 60), t, 'win', hw, l + 10, r - 10)] * 3
        tl, tt, tr = self.taskbar_top(); sp += [(random.randint(tl + 80, max(tl + 81, tr - 300)), tt, 'taskbar', None, tl + 10, tr - 260)] * 3
        ix = random.choice((40, 115)); sp.append((ix, 8 + 100 * random.randint(0, 5), 'icon', None, ix - 30, ix + 30))
        return sp
    def fg_window(self):
        try:
            import ctypes; hw = ctypes.windll.user32.GetForegroundWindow()
            if hw and hw != getattr(self, 'hwnd', 0):
                l, t, r, b = self.win_rect(hw)
                if r - l > 200 and t > 20: return (min(max(l + 80, (l + r) // 2 + 120), r - 60), t, 'win', hw, l + 10, r - 10)
        except Exception: pass
        return None
    # ---- background: net speed (60s) + hub (AI job busy, 15s) ----
    def probe(self):
        import math
        while True:
            try:
                t = time.time()
                with U.urlopen(U.Request(self.base + '/bb/static/notes/doyel/fly0.png?p=%d' % t, headers={'User-Agent': 'RoyalLink/2.1', 'Cache-Control': 'no-cache'}), timeout=15) as r: n = len(r.read())
                self.mbps = n * 8 / max(time.time() - t, 0.02) / 1e6; self.net = max(0.35, min(2.6, 0.4 + 0.5 * math.log2(1 + self.mbps)))
            except Exception: self.net = None; self.mbps = 0
            for _ in range(4):
                try: self.busy = int(self.get('/bb/link/hub?token=' + self.tok).get('device', {}).get('busy') or 0)
                except Exception: pass
                time.sleep(15)
    # ---- sound: soft synthesized chirp (off by default; file ~/.rbt_sound turns it on) ----
    def chirp(self):
        if not self.sound: return
        try:
            import winsound, math, struct, wave, random
            if not getattr(self, '_wav', None):
                sr = 22050; fr = b''
                for n in range(3):
                    f0 = random.uniform(2600, 3400); L = int(sr * 0.09)
                    for i in range(L):
                        t = i / sr; f = f0 + 1800 * t / 0.09; a = math.sin(math.pi * i / L) * 0.25
                        fr += struct.pack('<h', int(32767 * a * math.sin(2 * math.pi * f * t)))
                    fr += b'\0\0' * int(sr * 0.05)
                b = io.BytesIO(); w = wave.open(b, 'wb'); w.setnchannels(1); w.setsampwidth(2); w.setframerate(sr); w.writeframes(fr); w.close(); self._wav = b.getvalue()
            winsound.PlaySound(self._wav, winsound.SND_MEMORY | winsound.SND_ASYNC)
        except Exception: pass
    # ---- props drawn beside the bird: crumbs, insect, water drop, splash ----
    def props(self, kind=None):
        c = getattr(self,'cv',None)
        if c is None: return
        c.delete('prop')
        if not kind: return
        import random; bx = 112 if self.face > 0 else 16
        if kind == 'crumbs':
            for _ in range(4): x = bx + random.randint(-10, 8) * self.face; c.create_oval(x, 120, x + 3, 123, fill=random.choice(('#c8a165', '#a0763d', '#e0c68f')), outline='', tags='prop')
        elif kind == 'insect':
            x = bx + random.randint(-6, 6); c.create_oval(x, 119, x + 7, 123, fill='#3e7d2c', outline='#264d1b', tags='prop'); c.create_line(x + 7, 120, x + 10, 118, fill='#264d1b', tags='prop')
        elif kind == 'water':
            x = bx - 4 * self.face; c.create_oval(x - 9, 120, x + 9, 125, fill='#7ec8f0', outline='#4a9cc8', tags='prop')
        elif kind == 'splash':
            for _ in range(7): x, y = 64 + random.randint(-40, 40), 70 + random.randint(-30, 40); c.create_oval(x, y, x + 4, y + 5, fill='#9bd6f5', outline='', tags='prop')
    # ---- the brain ----
    def hour(self): return time.gmtime(time.time() + 6 * 3600).tm_hour     # Dhaka (UTC+6)
    def go(self, state, dur=None):
        import random; self.state = state; self.t0 = time.time(); self.seq = []; self.props(None)
        self.until = self.t0 + (dur if dur is not None else random.uniform(8, 20) if state == 'fly' else random.uniform(4, 10))
    def pick_target(self, perch=False, spot=None, near=None):
        import random; x0, y0, x1, y1 = self.bounds()
        if perch or spot:
            sp = [spot] if spot else self.spots()
            if near and not spot: sp.sort(key=lambda s: abs(s[0] - near[0]) + abs(s[1] - near[1])); sp = sp[:3]
            if sp:
                x, y, kind, hw, a, b = random.choice(sp); self.perch_on = (kind, hw, y, a, b)
                self.tx, self.ty = min(max(x - self.S // 2, x0), x1), y - self.FOOT; return
        self.perch_on = None
        if near: self.tx, self.ty = min(max(near[0] - self.S // 2, x0), x1), min(max(near[1] - self.S - 20, y0), y1)
        else: self.tx, self.ty = random.uniform(x0, x1), random.uniform(y0, y1 - 80)
    def choose(self):
        """Weighted next activity while perched — depends on time of day, surface, network, cursor and how long since flying."""
        import random; h = self.hour(); night = h >= 22 or h < 5; morning = 5 <= h < 9; noon = 12 <= h < 15
        on_edge = self.perch_on and self.perch_on[4] - self.perch_on[3] > 160
        w = {'idle': 3, 'look': 3, 'cock': 2, 'preen': 2, 'walk': 3 if on_edge else 0, 'forage': 3 if on_edge else 1, 'drink': 1.5 if noon else 0.6,
             'sing': 3 if morning else 1, 'bathe': 1.2 if noon else 0.3, 'hop': 1.5, 'fly': 0 if self.net is None or not self.roam else 1 + (time.time() - self.t_fly > 90) * 2.5,
             'sleep': 30 if night else 0.2, 'curious': 0}
        px, py = self.root.winfo_pointerxy()
        if time.time() - self.t_mouse > 20 and abs(px - self.x - 64) + abs(py - self.y - 64) < 700: w['curious'] = 3
        k = random.choices(list(w), list(w.values()))[0]; self.do(k)
    def do(self, k):
        """Build a short timed sequence [(pose, seconds, dx, prop)] for an activity."""
        import random; f = self.face; S = []
        if k == 'idle': S = [('perch0', random.uniform(1.5, 4), 0, None)]
        elif k == 'look': S = [('look0', random.uniform(.8, 2), 0, None), ('perch0', .6, 0, None), ('down0', random.uniform(.6, 1.5), 0, None), ('perch0', .5, 0, None)]
        elif k == 'cock': S = [('cock0', .5, 0, None), ('cock1', .4, 0, None), ('cock0', .6, 0, None), ('perch0', 1, 0, None)] * random.randint(1, 2)
        elif k == 'preen': S = [('preen0', random.uniform(1.5, 3), 0, None), ('perch0', .4, 0, None), ('preen0', random.uniform(1, 2.5), 0, None), ('shake0', .35, 0, None), ('perch0', .8, 0, None)]
        elif k == 'walk':
            if random.random() < .4: self.face = -self.face
            S = [('walk%d' % (i % 3), .13, 4, None) for i in range(random.randint(8, 24))] + [('perch0', .8, 0, None)]
        elif k == 'forage':
            S = [('walk%d' % (i % 3), .13, 4, None) for i in range(random.randint(3, 9))]
            for _ in range(random.randint(2, 4)):
                prop = random.choice(('crumbs', 'crumbs', 'insect'))
                S += [('down0', .4, 0, prop), ('peck1', .25, 0, prop), ('peck0', .18, 0, prop), ('peck1', .18, 0, prop), ('peck0', .18, 0, None), ('perch0', .5, 0, None), ('walk1', .13, 4, None), ('walk2', .13, 4, None)]
        elif k == 'drink': S = [('peck1', .5, 0, 'water'), ('peck0', .6, 0, 'water'), ('drink0', .7, 0, 'water'), ('peck0', .6, 0, 'water'), ('drink0', .7, 0, 'water'), ('perch0', .6, 0, None)]
        elif k == 'sing': S = [('sing0', .7, 0, 'chirp'), ('perch0', .3, 0, None), ('sing0', .9, 0, 'chirp'), ('cock0', .6, 0, None), ('sing0', .7, 0, 'chirp'), ('perch0', 1, 0, None)]
        elif k == 'bathe': S = [('peck0', .5, 0, 'water'), ('shake0', .25, 0, 'splash'), ('perch0', .12, 0, 'splash'), ('shake0', .25, 0, 'splash'), ('perch0', .12, 0, None), ('shake0', .3, 0, 'splash'), ('preen0', 2, 0, None), ('perch0', .8, 0, None)]
        elif k == 'hop': S = [('hop0', .18, 0, None), ('hop1', .25, 14, None), ('perch0', .6, 0, None)]
        elif k == 'sleep': self.go('sleep', float('inf') if self.hour() >= 22 or self.hour() < 5 else random.uniform(60, 240)); self.pose = 'sleep0'; self.paint(); return
        elif k == 'curious':
            px, py = self.root.winfo_pointerxy(); self.pick_target(True, near=(px, py)); self.go('fly', 30); self.mood = 'curious'; return
        elif k == 'fly': self.pick_target(random.random() < .3); self.go('fly'); self.t_fly = time.time(); return
        self.seq = S; self.seq_t = 0
    def step_seq(self, now):
        if not self.seq: return False
        if now < self.seq_t: return True
        pose, dur, dx, prop = self.seq.pop(0); self.pose = pose; self.seq_t = now + dur
        if dx and self.perch_on:
            nx = self.x + dx * self.face; a, b = self.perch_on[3] - 64, self.perch_on[4] - 64
            if not a <= nx <= b: self.face = -self.face; nx = self.x + dx * self.face
            self.x = nx; self.place()
        if prop == 'chirp': self.chirp(); self.props(None)
        else: self.props(prop)
        if pose == 'hop1': self.root.geometry('+%d+%d' % (self.x, self.y - 10))
        elif pose == 'perch0': self.place()
        self.paint(); return True
    def place(self): self.root.geometry('+%d+%d' % (self.x, self.y))
    def react(self, what):
        """External events: 'clip' (new copy → fly to cursor), 'happy', 'think', 'sad' (from the panel)."""
        if self.state in ('sleep',) and what != 'clip': return
        px, py = self.root.winfo_pointerxy()
        if what == 'clip' and self.state != 'pinned' and self.net is not None:
            self.pick_target(False, near=(px + 60, py)); self.go('fly', 6); self.mood = 'visit'
        elif what == 'happy' and self.state != 'fly': self.do('sing')
        elif what == 'think' and self.state != 'fly': self.seq = [('look0', .8, 0, None), ('down0', .8, 0, None)] * 3
        elif what == 'sad' and self.state != 'fly': self.seq = [('down0', 2, 0, None), ('perch0', .5, 0, None)]
    def land_here(self):
        self.go('perch'); self.seq = []; self.pose = 'perch0'; self.chk = time.time(); self.paint()
    def roam_tick(self):
        import random, math
        r = self.root; dt = 40; now = time.time()
        try:
            if self.drag: dt = 60; return
            # cursor tracking → startle / curiosity
            px, py = r.winfo_pointerxy(); vx_, vy_ = (px - self.lp[0]) / max(now - self.lp[2], .01), (py - self.lp[1]) / max(now - self.lp[2], .01)
            if abs(px - self.lp[0]) + abs(py - self.lp[1]) > 2: self.t_mouse = now
            self.lp = (px, py, now); cx, cy = self.x + 64, self.y + 70; dist = math.hypot(px - cx, py - cy)
            toward = (vx_ * (cx - px) + vy_ * (cy - py)) > 0
            if math.hypot(vx_, vy_) > 1800 and toward and dist < 260 and self.state not in ('pinned',) and self.net is not None and now > self.no_startle:
                self.face = 1 if cx > px else -1; x0, y0, x1, y1 = self.bounds()
                self.tx = min(max(self.x + self.face * random.uniform(300, 600), x0), x1); self.ty = max(y0, self.y - random.uniform(150, 350)); self.perch_on = None
                self.go('fly', random.uniform(6, 12)); self.mood = 'startled'; self.no_startle = now + 4; self.chirp()
            # AI job running → go sit on the active window and 'work'
            if self.busy and self.state not in ('pinned', 'fly') and not (self.perch_on and self.perch_on[0] == 'busy'):
                fw = self.fg_window()
                if fw: self.pick_target(spot=fw); self.perch_on = ('busy',) + self.perch_on[1:]; self.go('fly', 30)
            st = self.state
            if st in ('perch', 'pinned', 'sleep'):
                dt = 70
                if st == 'sleep':
                    if self.pose != 'sleep0': self.pose = 'sleep0'; self.paint()
                    h = self.hour()
                    if now > self.until or (5 <= h < 22 and self.until == float('inf')): self.go('perch', 2); self.pose = 'shake0'; self.paint()
                    dt = 400
                elif not self.step_seq(now):
                    if st == 'pinned':
                        if now > self.until: self.pin(False)          # dropped by user: stays 30–120s, then leaves on its own
                        else: self.do(random.choice(['idle', 'look', 'cock', 'preen', 'walk', 'forage', 'sing', 'hop', 'idle'])); self.perch_on = self.perch_on or ('pin', None, self.y + self.FOOT, self.x - 60 + 64, self.x + 60 + 64)
                    elif self.busy and self.perch_on and self.perch_on[0] == 'busy': self.seq = [('peck1', .2, 0, None), ('peck0', .15, 0, None), ('look0', .6, 0, None), ('perch0', .5, 0, None)]
                    elif now > self.until: self.until = now + random.uniform(.5, 2); self.choose()
                    else: self.pose = 'perch0'; self.paint()
                if st == 'perch' and self.perch_on and self.perch_on[1] and now - self.chk > 1:     # window moved / closed → take off
                    self.chk = now
                    try:
                        import ctypes; u = ctypes.windll.user32; hw = self.perch_on[1]
                        if not u.IsWindow(hw) or not u.IsWindowVisible(hw) or u.IsIconic(hw) or abs(self.win_rect(hw)[1] - self.perch_on[2]) > 3: self.do('fly')
                    except Exception: pass
                if st == 'perch' and not self.busy and self.perch_on and self.perch_on[0] == 'busy': self.perch_on = ('win',) + self.perch_on[1:]
                if self.follow and st == 'perch' and dist > 260: self.pick_target(False, near=(px - 70, py)); self.go('fly', 30)
            else:   # flying
                if dist < 120 and not self.perch_on and self.mood not in ('startled', 'visit') and not self.follow:   # hover-stop
                    self.wing = (self.wing + 1) % 8; self.pose = 'fly%d' % self.wing; self.paint(); dt = 60; return
                if self.follow: self.tx, self.ty = px - 150 if self.face > 0 else px + 30, py - 110; self.perch_on = None
                elif (self.net is None or not self.roam or now > self.until) and not self.perch_on and self.mood not in ('visit',): self.pick_target(True)
                sp = 3.2 * self.speed * (self.net or 0.6) * (1.25 if self.perch_on else 1) * (2.4 if self.mood == 'startled' else 1)
                dx, dy = self.tx - self.x, self.ty - self.y; d = math.hypot(dx, dy)
                if d < sp + 1:
                    self.x, self.y = self.tx, self.ty; self.place()
                    if self.follow: self.pose = 'fly%d' % self.wing; self.wing = (self.wing + 1) % 8; self.paint()
                    elif self.perch_on: self.land_here(); self.mood = None; self.do('look') if random.random() < .5 else None
                    elif self.mood == 'visit': self.mood = None; self.perch_on = ('pin', None, self.y + self.FOOT, self.x - 40 + 64, self.x + 40 + 64); self.land_here(); self.do('sing'); self.until = now + 4   # hovering by the cursor
                    elif self.mood == 'startled': self.mood = None; self.pick_target(True)
                    else: self.pick_target(False)
                else:
                    if abs(dx) > 2: self.face = 1 if dx > 0 else -1
                    self.x += dx / d * sp; self.y += dy / d * sp
                    if self.glide > 0: self.glide -= 1; self.pose = 'glide0'
                    else:
                        self.wing = (self.wing + 1) % 8; self.pose = 'fly%d' % self.wing
                        if self.wing == 2 and dy > -0.3 * abs(dx) and d > 250 and random.random() < 0.3 and self.mood != 'startled': self.glide = random.randint(10, 25)
                    r.geometry('+%d+%d' % (self.x, self.y + (0 if self.glide else 3 * math.sin(now * 9)))); self.paint()
                dt = int(max(24, 48 / max(0.6, self.net or 0.6) ** 0.5 / (1.6 if self.mood == 'startled' else 1)))
        finally:
            r.after(dt, self.roam_tick)
            if now - self.t_stat > 2: self.t_stat = now; self.panel_send({'cmd': 'status', 's': self.bstatus()})
    def bstatus(self): return {'state': self.state if not self.seq or self.state != 'perch' else ('walk' if self.pose.startswith('walk') else 'forage' if self.pose.startswith('peck') else 'perch'),
                              'net': self.net, 'mbps': round(self.mbps, 1), 'speed': self.speed, 'sound': self.sound, 'roam': self.roam, 'paused': self.paused, 'busy': self.busy}
    def pin(self, on):
        import random
        if on: self.go('pinned', random.uniform(30, 120)); self.perch_on = None; self._save_pos(self.x, self.y)
        else: self.pick_target(False); self.go('fly'); self.t_fly = time.time()
        self.paint()
    def switch_mascot(self, m):
        import sys
        try: open(MASCOT_F, 'w').write(m)
        except Exception: pass
        try: self.pp.kill()
        except Exception: pass
        try: self.root.destroy()
        except Exception: pass
        os.execv(sys.executable, [sys.executable] + sys.argv)
    def flag(self, name, on):
        f = os.path.expanduser('~/.rbt_' + name)
        if on: open(f, 'w').close()
        elif os.path.exists(f): os.remove(f)
    def bird_cmd(self, c, arg=''):
        import random
        if c == 'mascot': return self.switch_mascot(arg)
        if c == 'fly': self.follow = False; self.pin(False) if self.state != 'fly' else None
        elif c == 'sit': self.follow = False; self.pick_target(True); self.go('fly', 30)
        elif c == 'follow': self.follow = not self.follow; self.go('fly', 1e9) if self.follow else self.pick_target(True)
        elif c == 'sleep': self.do('sleep') if self.state != 'sleep' else self.go('perch', 2)
        elif c == 'forage':
            if self.state == 'fly': self.pick_target(True); self.mood = None
            else: self.do('forage')
        elif c == 'sing': self.chirp(); self.do('sing') if self.state != 'fly' else None
        elif c == 'roam': self.roam = not self.roam; self.flag('noroam', not self.roam)
        elif c == 'sound': self.sound = not self.sound; self.flag('sound', self.sound); self.chirp()
        elif c == 'speed':
            try: self.speed = float(arg)
            except ValueError: pass
        elif c == 'pause': self.toggle_pause()
        elif c == 'hide': self.root.withdraw(); self.root.after(10 * 60 * 1000, self.root.deiconify)
        elif c == 'hide_briefly': self.root.withdraw(); self.root.after(1500, self.root.deiconify)
        elif c in ('happy', 'think', 'sad'): self.react(c)
        self.paint()
    # ---- panel: pywebview glass panel if installed, else the tkinter quick window ----
    def panel_send(self, o):
        p = getattr(self, 'pp', None)
        if p and p.poll() is None:
            try: p.stdin.write((json.dumps(o, ensure_ascii=False) + '\n').encode()); p.stdin.flush()
            except Exception: pass
    def open_panel(self, tab=''):
        import importlib.util, subprocess, sys
        x0, y0, x1, y1 = self.bounds(); px = self.x - 430 if self.x > x0 + 460 else self.x + self.S; py = max(y0 + 10, min(self.y - 300, y1 + self.S - 660))
        here = os.path.dirname(os.path.abspath(__file__)); script = os.path.join(here, 'royal_panel.py')
        if importlib.util.find_spec('webview') and os.path.exists(script):
            if not (getattr(self, 'pp', None) and self.pp.poll() is None):
                exe = sys.executable.replace('python.exe', 'pythonw.exe') if sys.executable.endswith('python.exe') else sys.executable
                self.pp = subprocess.Popen([exe, script], stdin=subprocess.PIPE, stdout=subprocess.PIPE, creationflags=getattr(subprocess, 'CREATE_NO_WINDOW', 0))
                self.panel_send({'base': self.base, 'token': self.tok, 'x': px, 'y': py})
                threading.Thread(target=self.panel_reader, daemon=True).start()
            else: self.panel_send({'cmd': 'show', 'x': px, 'y': py, 'tab': tab})
            self.panel_send({'cmd': 'status', 's': self.bstatus()})
        else: self.open_mini()
    def panel_reader(self):
        for ln in self.pp.stdout:
            try:
                o = json.loads(ln)
                if 'bird' in o: self.root.after(0, lambda o=o: self.bird_cmd(o['bird'], o.get('arg', '')))
            except Exception: pass
    def run(self):
        import tkinter as tk, math, random
        r = self.root = tk.Tk(); r.overrideredirect(True); r.attributes('-topmost', True); r.configure(bg='#010203')
        try: r.attributes('-transparentcolor', '#010203')
        except Exception: pass
        x0, y0, x1, y1 = self.bounds(); pos = self._load_pos() or (x1, (y0 + y1) // 2)
        self.x, self.y = pos; self.face = -1; self.pose = 'perch0'; self.wing = 0; self.glide = 0; self.perch_on = None; self.chk = 0; self.seq = []; self.seq_t = 0
        self.net = 1.0; self.mbps = 0; self.busy = 0; self.mood = None; self.follow = False; self.t_fly = time.time(); self.t_mouse = time.time(); self.lp = (0, 0, time.time()); self.no_startle = 0; self.t_stat = 0
        self.sound = os.path.exists(os.path.expanduser('~/.rbt_sound')); threading.Thread(target=self.probe, daemon=True).start()
        self.roam = not os.path.exists(os.path.expanduser('~/.rbt_noroam')); self.speed = 1.0; self.drag = False
        self.go('perch', 3)
        r.geometry('%dx%d+%d+%d' % (self.S, self.S, self.x, self.y))
        self.cv = tk.Canvas(r, width=self.S, height=self.S, bg='#010203', highlightthickness=0, cursor='hand2'); self.cv.pack()
        d = {}
        def down(e): self.drag = True; d.update(x=e.x_root, y=e.y_root, wx=self.x, wy=self.y, m=False)
        def move(e):
            dx, dy = e.x_root - d['x'], e.y_root - d['y']
            if abs(dx) + abs(dy) > 4: d['m'] = True; self.wing = (self.wing + 1) % 8; self.pose = 'fly%d' % self.wing; self.props(None); self.paint()
            self.x, self.y = d['wx'] + dx, d['wy'] + dy; self.place()
        def up(e):
            self.drag = False
            if d.get('m'): self.pin(True)          # dropped somewhere → sits & fidgets 30–120s, then flies off by itself
            else:
                if self.state == 'sleep': self.go('perch', 3); self.pose = 'shake0'; self.paint()
                d['click'] = r.after(300, self.open_panel)
        def dbl(e):
            if d.get('click'): r.after_cancel(d.pop('click'))
            self.pin(False)
        self.cv.bind('<ButtonPress-1>', down); self.cv.bind('<B1-Motion>', move); self.cv.bind('<ButtonRelease-1>', up); self.cv.bind('<Double-Button-1>', dbl)
        menu = tk.Menu(r, tearoff=0)
        for lbl, c in (('✨ প্যানেল খুলুন', 'panel'), ('📝 দ্রুত নোট (সাধারণ)', 'mini'), (self.LB[0], 'fly'), (self.LB[1], 'sit'), ('🎯 কার্সর অনুসরণ', 'follow'), ('😴 ঘুমাও / জাগো', 'sleep'),
                       (self.LB[2], 'forage'), ('🔊 শব্দ চালু/বন্ধ', 'sound'), ('🌀 ঘোরা চালু/বন্ধ', 'roam'), ('⏸ / ▶ ক্লিপবোর্ড ধরা', 'pause')):
            menu.add_command(label=lbl, command=(lambda c=c: self.open_panel() if c == 'panel' else self.open_mini() if c == 'mini' else self.bird_cmd(c)))
        sm = tk.Menu(menu, tearoff=0)
        for lbl, v in (('ধীর', 0.5), ('মাঝারি', 1.0), ('দ্রুত', 2.0)): sm.add_command(label=lbl, command=lambda v=v: self.bird_cmd('speed', v))
        menu.add_cascade(label='⚡ গতি', menu=sm)
        menu.add_command(label='📖 নোটবুক খুলুন', command=lambda: __import__('webbrowser').open(self.base + '/notes/'))
        menu.add_command(label='বাবল লুকান (এই সেশনে)', command=r.withdraw)
        menu.add_command(label=self.LB[3], command=lambda: self.bird_cmd('mascot', 'doyel' if isinstance(self, Girl) else 'girl'))
        def popup(e):
            menu.entryconfig(10, label='⚡ গতি — নেট %s' % ('অফলাইন' if self.net is None else '%.1f Mbps' % self.mbps)); menu.tk_popup(e.x_root, e.y_root)
        self.cv.bind('<Button-3>', popup)
        self.paint(); r.after(300, self.noactivate); r.after(800, self.poll); r.after(500, self.roam_tick); r.mainloop()
    def _load_pos(self):
        try: return tuple(json.load(open(os.path.expanduser('~/.rbt_bubble.json'))))
        except Exception: return None
    def _save_pos(self, x, y):
        try: json.dump([x, y], open(os.path.expanduser('~/.rbt_bubble.json'), 'w'))
        except Exception: pass
    def open_mini(self):
        import tkinter as tk
        if self.mini and self.mini.winfo_exists(): self.mini.lift(); return
        w = self.mini = tk.Toplevel(self.root); w.title('রয়েল নোটবুক · দ্রুত নোট'); w.attributes('-topmost', True); w.configure(bg='#11264a')
        x = max(0, self.root.winfo_x() - 360); w.geometry('360x460+%d+%d' % (x, max(0, self.root.winfo_y() - 200)))
        F = ('Nirmala UI', 10)
        tk.Label(w, text='📒 দ্রুত নোট', bg='#11264a', fg='#d4af37', font=('Nirmala UI', 12, 'bold')).pack(anchor='w', padx=8, pady=(8, 2))
        txt = tk.Text(w, height=7, wrap='word', font=F, bg='#172f5a', fg='white', insertbackground='white'); txt.pack(fill='x', padx=8); txt.focus_set()
        st = tk.Label(w, text='', bg='#11264a', fg='#9fb0cf', font=F); 
        def save():
            body = txt.get('1.0', 'end').strip()
            if not body: return
            try: self.post('/bb/link/note', {'token': self.tok, 'body': body}); txt.delete('1.0', 'end'); st.config(text='✓ নোটবুকে রাখা হয়েছে')
            except Exception as e: st.config(text='⚠ পাঠানো যায়নি: ' + str(e)[:60])
        bf = tk.Frame(w, bg='#11264a'); bf.pack(fill='x', padx=8, pady=4)
        tk.Button(bf, text='💾 রাখুন (Ctrl+Enter)', command=save, bg='#ff8c1a', fg='white', relief='flat', font=F).pack(side='left')
        tk.Button(bf, text='⏸ থামান' if not self.paused else '▶ চালু', command=lambda: (self.toggle_pause(), w.destroy(), self.open_mini()), relief='flat', font=F).pack(side='left', padx=4)
        tk.Button(bf, text='📖', command=lambda: __import__('webbrowser').open(self.base + '/notes/'), relief='flat', font=F).pack(side='left')
        st.pack(anchor='w', padx=8); txt.bind('<Control-Return>', lambda e: (save(), 'break'))
        tk.Label(w, text='সাম্প্রতিক কপি (ক্লিক = আবার কপি)', bg='#11264a', fg='#9fb0cf', font=F).pack(anchor='w', padx=8, pady=(6, 0))
        lb = tk.Listbox(w, font=F, bg='#0b1a33', fg='white', selectbackground='#d4af37', height=10); lb.pack(fill='both', expand=True, padx=8, pady=(0, 8))
        items = []
        def load():
            try:
                cl = self.get('/bb/link/clips?n=20&token=' + self.tok).get('clips', [])
                items[:] = cl; lb.delete(0, 'end')
                for c in cl: lb.insert('end', c['content'].replace('\n', ' ')[:70])
            except Exception as e: lb.insert('end', '⚠ লোড হয়নি')
        def pick(e):
            i = lb.curselection()
            if i: self.root.clipboard_clear(); self.root.clipboard_append(items[i[0]]['content']); st.config(text='📋 কপি হলো')
        lb.bind('<<ListboxSelect>>', pick); threading.Thread(target=lambda: w.after(0, load), daemon=True).start()
        w.bind('<Escape>', lambda e: w.destroy())

