def Clip(base, token, status=None):
    """Factory used by the launcher/tray: 'girl' unless ~/.rbt_mascot says 'doyel'."""
    try: m = open(MASCOT_F).read().strip()
    except Exception: m = 'girl'
    return (Doyel if m == 'doyel' else Girl)(base, token, status)

